// Keyboard layouts (the OS layout the user types with, e.g. Danish): key cap
// labels that replace the US ones, from vial-gui's keymaps.py and keymap/*.py
// (View > Keyboard layout). keymaps.json is generated by
// scripts/dump_keymaps.py; never edit it by hand.
//
// Only labels change. The keycodes sent to and stored on the keyboard are the
// same whatever layout is picked, as in vial-gui.

import raw from "./data/keymaps.json";

export interface KeyboardLayout {
  /** vial-gui's display name, also what is stored as the user's choice. */
  readonly name: string;
  /** Canonical QMK id (e.g. "KC_SCOLON") → key cap label ("Æ"), "\n" between shifted and plain. */
  readonly labels: Readonly<Record<string, string>>;
}

// JSON inference unions the label keys of all layouts, so the type is stated here.
export const KEYBOARD_LAYOUTS: readonly KeyboardLayout[] = raw.keymaps as KeyboardLayout[];

/** US QWERTY: no overrides. */
export const DEFAULT_KEYBOARD_LAYOUT = KEYBOARD_LAYOUTS[0];

export function findKeyboardLayout(name: string | null | undefined): KeyboardLayout {
  return KEYBOARD_LAYOUTS.find((l) => l.name === name) ?? DEFAULT_KEYBOARD_LAYOUT;
}
